def expected_turns(n: int, m: int, jumps: list[list[int]]) -> list[int] | None:
    from fractions import Fraction

    jump = {a: b for a, b in jumps}
    resolved = list(range(n + 1))

    for start in jump:
        path = []
        cell = start
        while cell in jump and resolved[cell] == cell:
            path.append(cell)
            cell = jump[cell]
        destination = resolved[cell]
        for cell in path:
            resolved[cell] = destination

    transitions = {}
    reachable = {0}
    queue = [0]

    for cell in queue:
        if cell == n:
            continue

        counts = {}
        for roll in range(1, m + 1):
            destination = cell + roll
            if destination > n:
                destination = 2 * n - destination
            destination = resolved[destination]
            counts[destination] = counts.get(destination, 0) + 1

            if destination not in reachable:
                reachable.add(destination)
                queue.append(destination)

        transitions[cell] = counts

    reverse = {cell: [] for cell in reachable}
    for cell, counts in transitions.items():
        for destination in counts:
            reverse[destination].append(cell)

    can_finish = {n}
    queue = [n]
    for cell in queue:
        for previous in reverse.get(cell, ()):
            if previous not in can_finish:
                can_finish.add(previous)
                queue.append(previous)

    if not reachable.issubset(can_finish):
        return None

    states = [cell for cell in reachable if cell != n]
    index = {cell: i for i, cell in enumerate(states)}
    size = len(states)

    matrix = [[0] * (size + 1) for _ in range(size)]
    for cell, i in index.items():
        matrix[i][i] = m
        matrix[i][size] = m
        for destination, count in transitions[cell].items():
            if destination != n:
                matrix[i][index[destination]] -= count

    previous_pivot = 1
    for k in range(size - 1):
        pivot = matrix[k][k]
        for i in range(k + 1, size):
            coefficient = matrix[i][k]
            for j in range(k + 1, size + 1):
                matrix[i][j] = (
                    matrix[i][j] * pivot - coefficient * matrix[k][j]
                ) // previous_pivot
            matrix[i][k] = 0
        previous_pivot = pivot

    solution = [Fraction(0) for _ in range(size)]
    for i in range(size - 1, -1, -1):
        value = Fraction(matrix[i][size])
        for j in range(i + 1, size):
            value -= matrix[i][j] * solution[j]
        solution[i] = value / matrix[i][i]

    answer = solution[index[0]]
    return [answer.numerator, answer.denominator]
